let currentLang=localStorage.getItem('tf_api_lang')||'en';
function tr(k){return (translations[currentLang]||translations.en)[k]||translations.en[k]||k}
function setLanguage(lang){currentLang=translations[lang]?lang:'en';localStorage.setItem('tf_api_lang',currentLang);applyLanguage();notify(({en:'Language updated',ru:'Язык изменён',az:'Dil dəyişdirildi',tr:'Dil güncellendi'})[currentLang]);}
function applyLanguage(){
 const nav=['api','dashboard','generator','banned','analytics','users','logs','settings','themes','security','backup','help'];
 document.querySelectorAll('.rail button[data-view]').forEach(b=>{let v=b.dataset.view;b.title=tr(v)});
 $('#topTitle').textContent=tr(document.querySelector('.view.active')?.id.replace('view-','')||'api');
 $('#languageSelect').value=currentLang;$('#languageHeading').textContent='🌐 '+tr('language');$('#languageDescription').textContent=tr('languageDesc');$('#languageLabel').textContent=tr('language');$('#saveSettingsBtn').textContent=tr('save');$('#settingsSubtitle').textContent=tr('settingsSub');
 const h1=document.querySelector('#view-api .heading h1');if(h1)h1.textContent=tr('api');
 const sub=document.querySelector('#view-api .heading p');if(sub)sub.textContent=tr('subtitle');
 const create=document.querySelector('#view-api .heading .create');if(create)create.textContent=tr('create');
 const th=document.querySelectorAll('#view-api thead th');['name','key','type','status','rate','usage','last','created','actions'].forEach((k,i)=>{if(th[i])th[i].textContent=tr(k)});
 $('#search').placeholder=tr('search');$('#statusFilter').options[0].text=tr('status');$('#typeFilter').options[0].text=tr('type');$('#resetFilters').textContent='↻ '+tr('reset');
 renderAll();
 document.querySelectorAll('.view .heading h1').forEach(el=>{let v=el.closest('.view').id.replace('view-','');el.textContent=tr(v)});
 const bp=document.querySelector('#view-backup .table-panel p');if(bp)bp.textContent=tr('backupSub');
 const bb=document.querySelectorAll('#view-backup .table-panel button, #view-backup .table-panel label');
 ['downloadTxt','importTxt','backupJson','restoreJson'].forEach((k,i)=>{if(bb[i])bb[i].textContent=tr(k)});
 const help=document.querySelector('#view-help .table-panel');if(help)help.textContent=tr('helpText');
}

function saveSettings(){notify(({en:'Settings saved locally',ru:'Настройки сохранены',az:'Parametrlər yadda saxlanıldı',tr:'Ayarlar kaydedildi'})[currentLang]);log('Settings saved','Dashboard preferences')}
renderSettings();renderThemes();renderSecurity();renderAll();applyLanguage();
 const sg=$('#settingsGrid');if(sg&&!$('#globalDeviceReset'))sg.insertAdjacentHTML('beforeend',`<div class="setting-card" id="globalDeviceReset"><h3>Device session control</h3><p>Review all connected devices or remove every active device session. Banned keys are not changed.</p><button class="secondary" onclick="showAllDevices()">View active devices</button> <button class="secondary" onclick="kickEveryDevice()">Remove all active devices</button></div>`);
</script></body></html>
